CommitDate: Wed Apr 15 21:58:13 2026 +1200

    Bug 1970022 - Remove unused argument in nsIMsgDBView.getCommandStatus. r=mkmelin
    This argument is never used and it makes calling the function much more complicated.

    Differential Revision: https://phabricator.services.mozilla.com/D294385

diff --git a/mail/base/content/SearchDialog.js b/mail/base/content/SearchDialog.js
index 92fff806856..e8a68d57e24 100644
--- a/mail/base/content/SearchDialog.js
+++ b/mail/base/content/SearchDialog.js
@@ -459,22 +459,6 @@ FolderDisplayWidget.prototype = {
    */
   // @{

-  /**
-   * @returns {boolean} true if there is a db view and the command is enabled on the view.
-   *  This function hides some of the XPCOM-odditities of the getCommandStatus
-   *  call.
-   */
-  getCommandStatus(aCommandType) {
-    // no view means not enabled
-    if (!this.view.dbView) {
-      return false;
-    }
-    const enabledObj = {},
-      checkStatusObj = {};
-    this.view.dbView.getCommandStatus(aCommandType, enabledObj, checkStatusObj);
-    return enabledObj.value;
-  },
-
   /**
    * Make code cleaner by allowing peoples to call doCommand on us rather than
    *  having to do folderDisplayWidget.view.dbView.doCommand.
diff --git a/mail/base/content/about3Pane.js b/mail/base/content/about3Pane.js
index ab4e884dee7..986a4f0c036 100644
--- a/mail/base/content/about3Pane.js
+++ b/mail/base/content/about3Pane.js
@@ -7444,10 +7444,8 @@ commandController.registerCallback(
     // enabled for junk. The junk type picks up possible dummy message headers,
     // while the runJunkControls will prevent running on XF virtual folders.
     return (
-      commandController._getViewCommandStatus(Ci.nsMsgViewCommandType.junk) &&
-      commandController._getViewCommandStatus(
-        Ci.nsMsgViewCommandType.runJunkControls
-      )
+      gDBView?.getCommandStatus(Ci.nsMsgViewCommandType.junk) &&
+      gDBView?.getCommandStatus(Ci.nsMsgViewCommandType.runJunkControls)
     );
   }
 );
diff --git a/mail/base/content/mailCommon.js b/mail/base/content/mailCommon.js
index d09eb48a33f..f35650d0ce9 100644
--- a/mail/base/content/mailCommon.js
+++ b/mail/base/content/mailCommon.js
@@ -633,7 +633,7 @@ var commandController = {
         return gDBView?.msgFolder?.getNumUnread(false) > 0;
       case "cmd_markAsJunk":
       case "cmd_markAsNotJunk":
-        return this._getViewCommandStatus(Ci.nsMsgViewCommandType.junk);
+        return gDBView?.getCommandStatus(Ci.nsMsgViewCommandType.junk);
       case "cmd_archive":
         return (
           !isDummyMessage &&
@@ -663,9 +663,7 @@ var commandController = {
       case "cmd_deleteMessage":
         return canMove();
       case "cmd_shiftDeleteMessage":
-        return this._getViewCommandStatus(
-          Ci.nsMsgViewCommandType.deleteNoTrash
-        );
+        return gDBView?.getCommandStatus(Ci.nsMsgViewCommandType.deleteNoTrash);
       case "cmd_createFilterFromMenu":
         return (
           numSelectedMessages == 1 &&
@@ -676,17 +674,12 @@ var commandController = {
         if (gViewWrapper?.showGroupedBySort) {
           return false;
         }
-        const enabledObj = {};
-        const checkStatusObj = {};
-        gViewWrapper.dbView.getCommandStatus(
-          Ci.nsMsgViewCommandType.toggleThreadWatched,
-          enabledObj,
-          checkStatusObj
+        return gDBView?.getCommandStatus(
+          Ci.nsMsgViewCommandType.toggleThreadWatched
         );
-        return enabledObj.value;
       }
       case "cmd_applyFilters": {
-        return this._getViewCommandStatus(Ci.nsMsgViewCommandType.applyFilters);
+        return gDBView?.getCommandStatus(Ci.nsMsgViewCommandType.applyFilters);
       }
     }

@@ -730,21 +723,6 @@ var commandController = {
     }
   },

-  _getViewCommandStatus(commandType) {
-    if (!gViewWrapper?.dbView) {
-      return false;
-    }
-
-    const enabledObj = {};
-    const checkStatusObj = {};
-    gViewWrapper.dbView.getCommandStatus(
-      commandType,
-      enabledObj,
-      checkStatusObj
-    );
-    return enabledObj.value;
-  },
-
   /**
    * Toggle the state of a message tag on the selected messages (based on the
    * state of the first selected message, like for starring).
diff --git a/mail/base/content/msgHdrView.js b/mail/base/content/msgHdrView.js
index 1baf5da7917..97aa235d9d2 100644
--- a/mail/base/content/msgHdrView.js
+++ b/mail/base/content/msgHdrView.js
@@ -3661,7 +3661,7 @@ function updateHeaderToolbarButtons() {
   archiveButton.disabled = !MessageArchiver.canArchive([gMessage]);
   const junkScore = gMessage.getStringProperty("junkscore");
   let hideJunk = junkScore == Ci.nsIJunkMailPlugin.IS_SPAM_SCORE;
-  if (!commandController._getViewCommandStatus(Ci.nsMsgViewCommandType.junk)) {
