@@ -230,8 +230,8 @@ interface nsIMsgDBView : nsISupports

   void doCommand(in nsMsgViewCommandTypeValue command);
   void doCommandWithFolder(in nsMsgViewCommandTypeValue command, in nsIMsgFolder destFolder);
